import numpy as np; W=dict(np.load('weights.npz'))
for l in range(4):
  for j in range(6):
    s=slice(64*j,64*j+64)
    Q=W[f'W_q.{l}'][s];K=W[f'W_k.{l}'][s];V=W[f'W_v.{l}'][s];O=W[f'W_o.{l}'][:,s]
    qk=np.linalg.svd(Q.T@K,compute_uv=False);ov=np.linalg.svd(O@V,compute_uv=False)
    # bias-like: K mean direction
    print(l,j,'qk',qk[:4].round(2),'ov',ov[:3].round(2), 'qnorm',np.linalg.norm(Q).round(2),'knorm',np.linalg.norm(K).round(2),'Kln',np.linalg.norm(K@W[f'ln1_b.{l}']).round(2),'Qln',np.linalg.norm(Q@W[f'ln1_b.{l}']).round(2))
"

